const input = $input.first()?.json ?? {};
const cards = Array.isArray(input.cards) ? input.cards : [];

function decodeEntities(value = '') {
  return String(value)
    .replace(/&amp;/g, '&').replace(/&quot;/g, '"')
    .replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
    .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)));
}
function textFromHtml(html = '') {
  return decodeEntities(String(html)
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
}
function attr(html, name) {
  const re = new RegExp('\\b' + name + '\\s*=\\s*(["\\\'])(.*?)\\1', 'i');
  const m = String(html).match(re);
  return m ? decodeEntities(m[2]) : '';
}
function absoluteUrl(href = '') {
  if (/^https?:\/\//i.test(href)) return href;
  if (href.startsWith('//')) return 'https:' + href;
  return 'https://www2.hm.com' + (href.startsWith('/') ? href : '/' + href);
}
function pricesFromCard(html, text) {
  const found = [];
  // First look for currency-prefixed prices in visible card text.
  for (const m of text.matchAll(/(?:£|GBP\s*)\s*\d[\d,]*(?:\.\d{2})?/gi)) found.push(m[0].replace(/\s+/g, ' ').trim());
  // Some H&M markup stores the amount in a price-related element without the currency symbol.
  if (found.length === 0) {
    const priceFragments = String(html).match(/<(?:span|div|p)[^>]*(?:price|amount)[^>]*>[\s\S]*?<\/(?:span|div|p)>/gi) || [];
    for (const fragment of priceFragments) {
      const fragmentText = textFromHtml(fragment);
      for (const m of fragmentText.matchAll(/\d[\d,]*(?:\.\d{2})?/g)) found.push(m[0]);
    }
  }
  return [...new Set(found)];
}

if (!cards.length) {
  throw new Error('No product cards found. Check HTML output: the selector li:has(a[href*="productpage"]) returned zero cards.');
}

const output = [];
for (const rawCard of cards) {
  const card = String(rawCard ?? '');
  const href = (card.match(/href=["']([^"']*productpage[^"']*)["']/i) || [])[1] || '';
  if (!href) continue;
  const url = absoluteUrl(decodeEntities(href));
  const text = textFromHtml(card);

  let name = attr(card, 'alt') || attr(card, 'aria-label') || attr(card, 'title');
  if (!name) {
    const titleMatch = card.match(/<(?:h[1-6]|strong)[^>]*>([\s\S]*?)<\/(?:h[1-6]|strong)>/i);
    if (titleMatch) name = textFromHtml(titleMatch[1]);
  }
  if (!name) {
    const imageAlt = card.match(/<img\b[^>]*\balt=["']([^"']+)["']/i);
    if (imageAlt) name = decodeEntities(imageAlt[1]);
  }

  const prices = pricesFromCard(card, text);
  const discountMatch = text.match(/(?:-\s*)?\d{1,2}\s?%/);
  const discount = discountMatch ? discountMatch[0].replace(/\s+/g, '').replace(/^(\d)/, '-$1') : '';
  if (!name) {
    name = text.replace(/(?:£|GBP\s*)\s*\d[\d,]*(?:\.\d{2})?/gi, ' ')
      .replace(/(?:-\s*)?\d{1,2}\s?%/g, ' ')
      .replace(/\b(?:sale|view details|quick buy|add to bag)\b/gi, ' ')
      .replace(/\s+/g, ' ').trim();
  }

  // When two prices are present, H&M cards commonly show the original first and sale price last.
  // If only one price is present, put it in Price After and leave Price Before blank rather than guessing.
  const priceBefore = prices.length >= 2 ? prices[0] : '';
  const priceAfter = prices.length >= 2 ? prices[prices.length - 1] : (prices[0] || '');
  output.push({ json: {
    'Product names': name || 'H&M product',
    'Percentage Off': discount,
    'Price Before': priceBefore,
    'Price After': priceAfter,
    'Url': url
  }});
}
if (!output.length) throw new Error('Cards were found, but no product links could be extracted. Inspect one card HTML.');
return output;
